// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {Test} from "forge-std/Test.sol";
import {PaidOraclePilot} from "src/PaidOraclePilot.sol";

contract StubCoin {
    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }
}

contract StubParams {
    address public governor = address(0xBEEF);
}

contract StubVault {
    address public stablecoin;
    address public parameters;

    constructor() {
        stablecoin = address(new StubCoin());
        parameters = address(new StubParams());
    }

    function earn(uint256) external {}
}

/// A poster who posts toBlock = type(uint64).max (or any window past the chain head) must either be
/// refused, or must not make every later `propose` revert with a checked-arithmetic panic on
/// `last.toBlock + 1`. On the current code the first post is accepted and the second panics.
contract PilotToBlockOverflowTest is Test {
    PaidOraclePilot pilot;
    address poster = makeAddr("poster");

    function setUp() public {
        pilot = new PaidOraclePilot(address(new StubVault()), poster);
    }

    function test_maxToBlockMustNotBrickLaterEpochs() public {
        vm.prank(poster);
        try pilot.propose(bytes32(uint256(1)), 1e18, 1, type(uint64).max, "") returns (uint256) {}
        catch {
            return; // refused up front: fixed
        }
        vm.warp(block.timestamp + 7 days);
        vm.prank(poster);
        try pilot.propose(bytes32(uint256(1)), 1e18, 1, 2, "") returns (uint256) {}
        catch (bytes memory err) {
            assertEq(
                bytes4(err),
                PaidOraclePilot.WindowNotAfterPrevious.selector,
                "later epochs must be refused with the window error, not a panic"
            );
        }
    }
}

